    float sum = 0.0f;
    for (int k = 0; k < n; ++k) {
        sum += A[static_cast<std::size_t>(r) * static_cast<std::size_t>(n) + static_cast<std::size_t>(k)] *
               B[static_cast<std::size_t>(k) * static_cast<std::size_t>(n) + static_cast<std::size_t>(c)];
    }
    return sum;
}

