": "src/candidate.cpp", "sha256": "4a016af8ee51dc2bbf1af999b98bccc8c8a7c9d26be9384ca124c8dbd1fef0d5", "start_line": 5}], "mechanism": "138b initialise chaque élément par le produit de k=0, puis additionne les termes k=1…n−1; il évite ainsi un remplissage préalable de C. Il distribue les lignes avec parallel for statique et vectorise j. Cette source établit la structure, pas que l’initialisation fusionnée explique à elle seule son temps mesuré."}], "hypotheses": [{"claim": "Le parcours en blocs de plusieurs lignes de 1d24 peut bénéficier de la réutilisation de B par rapport au calcul ligne par ligne; les temps agrégés ne permettent pas d’isoler ce mécanisme.", "evidence_ids": ["087badc33fc24ab2", "1d24ff42665b46ce"], "proposed_test": "Comparer des hauteurs de bloc 1, 4, 8 et 16 avec même ordre k-i-j, même initialisation, même ordonnanceur statique et même noyau. Mesurer chacun des quatre couples taille-budget, puis confirmer toute variante retenue avec les répétitions de confirmation.", "stop_condition": "Ne pas privilégier une hauteur si elle n’apporte pas d’amélioration reproductible dans les cas visés, ou si la validation échoue; cela n’élimine pas d’autres décompositions."}, {"claim": "Initialiser au premier produit plutôt que par memset pourrait éviter une passe d’écriture de C et une synchronisation, mais les résultats de 138b ne testent pas cet effet isolément.", "evidence_ids": ["1d24ff42665b46ce", "138b6dc59d354031"], "proposed_test": "Dans le noyau en blocs de 1d24, conserver bloc, ordonnanceur et parcours, mais comparer memset suivi de k=0…n−1 à une affectation pour k=0 suivie des additions k=1…n−1. Vérifier les quatre cas et confirmer toute variante retenue.", "stop_condition": "Arrêter de privilégier l’initialisation fusionnée si elle n’améliore pas les temps de façon reproductible ou si elle échoue à la tolérance numérique."}], "observations": [{"claim": "Les moyennes rapportées sont : baseline 0.133355 s, 087bad 0.004315 s, 138b 0.004199 s et 1d24 0.00